import json, anthropic
client = anthropic.Anthropic()
TOOLS = [
  {"name": "get_weather", "description": "Get current weather for a city. Use for any weather question.",
   "input_schema": {"type": "object", "properties": {"city": {"type": "string"}}, "required": ["city"]}},
  {"name": "calculate", "description": "Evaluate an arithmetic expression such as '2450*0.18'. Use for all maths.",
   "input_schema": {"type": "object", "properties": {"expression": {"type": "string"}}, "required": ["expression"]}}]

def run_tool(name, args):
    if name == "get_weather":
        return json.dumps({"city": args["city"], "temp_c": 31, "sky": "humid"})  # stub data
    if name == "calculate":
        if not set(args["expression"]) <= set("0123456789+-*/(). "):
            raise ValueError("only digits and + - * / ( ) allowed")
        return str(eval(args["expression"], {"__builtins__": {}}))
    raise ValueError(f"unknown tool {name}")

messages = [{"role": "user", "content": "Weather in Pune? Also, what is 18% of 2450?"}]
for step in range(8):  # hard cap on loop iterations
    resp = client.messages.create(model="claude-sonnet-4-5", max_tokens=1024, tools=TOOLS, messages=messages)
    messages.append({"role": "assistant", "content": resp.content})
    if resp.stop_reason != "tool_use":
        break
    results = []  # parallel calls: one result per tool_use block, all in ONE user message
    for b in [b for b in resp.content if b.type == "tool_use"]:
        try:
            out, err = run_tool(b.name, b.input), False
        except Exception as e:
            out, err = f"Error: {e}", True
        results.append({"type": "tool_result", "tool_use_id": b.id, "content": out, "is_error": err})
    messages.append({"role": "user", "content": results})
print(next(b.text for b in resp.content if b.type == "text"))

