import ast, json, operator
import httpx

GEO_URL = "https://geocoding-api.open-meteo.com/v1/search"
WX_URL = "https://api.open-meteo.com/v1/forecast"
OPS = {ast.Add: operator.add, ast.Sub: operator.sub, ast.Mult: operator.mul,
       ast.Div: operator.truediv, ast.Mod: operator.mod, ast.Pow: operator.pow, ast.USub: operator.neg}

def _eval(node):
    # Walk the syntax tree. Never call eval() on model output.
    if isinstance(node, ast.Constant) and isinstance(node.value, (int, float)):
        return node.value
    if isinstance(node, ast.BinOp) and type(node.op) in OPS:
        if isinstance(node.op, ast.Pow) and abs(_eval(node.right)) > 100:
            raise ValueError("Exponent too large")
        return OPS[type(node.op)](_eval(node.left), _eval(node.right))
    if isinstance(node, ast.UnaryOp) and type(node.op) in OPS:
        return OPS[type(node.op)](_eval(node.operand))
    raise ValueError("Only numbers and + - * / % ** ( ) are allowed")

def calculator(expression: str) -> dict:
    return {"expression": expression, "result": _eval(ast.parse(expression, mode="eval").body)}

def get_weather(city: str) -> dict:
    geo = httpx.get(GEO_URL, params={"name": city, "count": 1}, timeout=10).json()
    if not geo.get("results"):
        raise ValueError(f"City '{city}' not found")  # becomes an observation, not a crash
    p = geo["results"][0]
    wx = httpx.get(WX_URL, params={"latitude": p["latitude"], "longitude": p["longitude"],
                   "current": "temperature_2m,wind_speed_10m"}, timeout=10).json()
    return {"city": p["name"], "country": p.get("country"),
            "temperature_c": wx["current"]["temperature_2m"], "wind_kmh": wx["current"]["wind_speed_10m"]}

# Tool definitions: the ONLY thing the model sees. A good description tells it when to use the tool.
TOOL_SCHEMAS = [
    {"type": "function", "function": {
        "name": "get_weather",
        "description": "Get current temperature (C) and wind speed (km/h) for one city. Call once per city.",
        "parameters": {"type": "object", "properties": {
            "city": {"type": "string", "description": "City name, e.g. 'Pune'"}},
            "required": ["city"], "additionalProperties": False}}},
    {"type": "function", "function": {
        "name": "calculator",
        "description": "Evaluate an arithmetic expression exactly. Use for any maths instead of guessing.",
        "parameters": {"type": "object", "properties": {
            "expression": {"type": "string", "description": "e.g. '(31.2 - 24.5) * 2'"}},
            "required": ["expression"], "additionalProperties": False}}},
]
REGISTRY = {"get_weather": get_weather, "calculator": calculator}

def run_tool(name: str, arguments_json: str) -> str:
    """Dispatch one tool call. Always returns a string (the observation)."""
    try:
        if name not in REGISTRY:
            raise KeyError(f"Unknown tool '{name}'")
        args = json.loads(arguments_json or "{}")  # the model sends arguments as a JSON string
        return json.dumps(REGISTRY[name](**args))
    except Exception as e:  # bad JSON, wrong args, network error, divide by zero, ...
        return json.dumps({"error": f"{type(e).__name__}: {e}"})

"""The same tools, exposed through the Model Context Protocol.

Any MCP host (Claude Desktop, IDE agents, MCP Inspector) can discover and call them.
The host does not need to know anything about our code.
"""
from mcp.server.fastmcp import FastMCP
from tools import calculator as calc_impl, get_weather as weather_impl

mcp = FastMCP("weather-calc")  # server name shown to clients

# PRIMITIVE 1 - Tools: model-invoked actions.
# FastMCP builds the input schema from the type hints and the description from the docstring.
# This is the same job TOOL_SCHEMAS does by hand in tools.py.
@mcp.tool()
def get_weather(city: str) -> dict:
    """Get current temperature (C) and wind speed (km/h) for one city."""
    return weather_impl(city)  # exceptions are returned to the client as an error result

@mcp.tool()
def calculator(expression: str) -> dict:
    """Evaluate an arithmetic expression exactly (+ - * / % ** and brackets)."""
    return calc_impl(expression)

# PRIMITIVE 2 - Resources: read-only context identified by a URI.
@mcp.resource("info://units")
def units() -> str:
    """Units used by this server's tools."""
    return "Temperature: degrees Celsius. Wind speed: km/h. Source: Open-Meteo current conditions."

# PRIMITIVE 3 - Prompts: reusable, user-selected templates.
@mcp.prompt()
def trip_check(city: str) -> str:
    """Ask whether today's weather suits outdoor travel in a city."""
    return f"Use get_weather for {city} and tell me if it is a good day to travel outdoors, with reasons."

if __name__ == "__main__":
    mcp.run()  # default transport: stdio (the host starts this script as a subprocess)

