"""Single entry point to the model. Every pattern in this project calls chat()."""
import os

from openai import OpenAI

# base_url=None means the default OpenAI endpoint.
# Set OPENAI_BASE_URL to use another OpenAI-compatible provider.
client = OpenAI(
    api_key=os.environ["OPENAI_API_KEY"],
    base_url=os.getenv("OPENAI_BASE_URL"),
)
MODEL = os.getenv("MODEL", "gpt-4o-mini")


def chat(messages, tools=None, json_mode=False):
    """Send messages and return the assistant message object."""
    kwargs = {"model": MODEL, "messages": messages, "temperature": 0.2}
    if tools:
        kwargs["tools"] = tools  # tool use: the model may return tool_calls
    if json_mode:
        # JSON mode: the prompt must mention JSON
        kwargs["response_format"] = {"type": "json_object"}
    response = client.chat.completions.create(**kwargs)
    return response.choices[0].message

"""Tool use: a plain Python function, its JSON schema, and a name-to-function registry."""
import json
import pathlib

CORPUS_PATH = pathlib.Path(__file__).resolve().parent.parent / "data" / "corpus.json"
CORPUS = json.loads(CORPUS_PATH.read_text(encoding="utf-8"))


def search_docs(query: str, k: int = 3) -> str:
    """Keyword search over the local corpus. Swap this for a web search API in real work."""
    words = {w.lower().strip("?,.") for w in query.split() if len(w) > 2}
    scored = []
    for doc in CORPUS:
        text = (doc["title"] + " " + doc["text"]).lower()
        score = sum(text.count(w) for w in words)
        if score:
            scored.append((score, doc))
    scored.sort(key=lambda pair: -pair[0])
    hits = [doc for _, doc in scored[:k]]
    # Tools return strings. The model reads this text as an observation.
    return json.dumps(hits) if hits else "No results."


# The schema tells the model what the tool does and which arguments it takes
TOOLS = [
    {
        "type": "function",
        "function": {
            "name": "search_docs",
            "description": "Search the knowledge base on agent design. Returns a JSON list of {id, title, text}.",
            "parameters": {
                "type": "object",
                "properties": {"query": {"type": "string", "description": "Keywords to search for"}},
                "required": ["query"],
            },
        },
    }
]

# Only functions listed here can run. The model cannot call arbitrary code.
REGISTRY = {"search_docs": search_docs}

