"""Three specialised workers. Each has one job and a narrow prompt."""
import os
from functools import lru_cache

from langchain.chat_models import init_chat_model
from langchain_core.messages import HumanMessage, SystemMessage, ToolMessage
from langchain_core.tools import tool
from pydantic import BaseModel, Field

from src.state import TeamState

# Tiny local knowledge base, so the demo needs no search API key
CORPUS = {
    "supervisor": "A supervisor agent routes work to workers; every worker reports back to it.",
    "handoff": "A handoff passes control and selected state directly from one agent to another.",
    "swarm": "In a swarm or network pattern, agents hand off to each other with no central router.",
    "state": "Shared state is visible to all agents; private state stays inside one agent.",
    "hierarchical": "Hierarchical teams nest supervisors: a top supervisor manages team supervisors.",
}


@lru_cache
def model():
    # Created lazily so tests can import this module without an API key
    return init_chat_model(os.getenv("MODEL", "openai:gpt-4o-mini"), temperature=0)


@tool
def search_notes(query: str) -> str:
    """Search the local knowledge base and return matching snippets."""
    hits = [text for key, text in CORPUS.items() if key in query.lower()]
    return "\n".join(hits) or "No results."


class Plan(BaseModel):
    steps: list[str] = Field(description="2-3 short research sub-questions")


def planner(state: TeamState) -> dict:
    plan = model().with_structured_output(Plan).invoke([
        SystemMessage("You are the planner. Only split the question into 2-3 sub-questions. Do not answer."),
        HumanMessage(state["question"]),
    ])
    return {"plan": plan.steps[:3], "trace": ["planner"]}


def researcher(state: TeamState) -> dict:
    llm = model().bind_tools([search_notes])
    notes = []
    for sub_q in state["plan"]:
        # PRIVATE context: a fresh message list for each sub-question, never written to TeamState
        private = [SystemMessage("You are the researcher. Call search_notes, then reply with a 1-2 sentence factual note."),
                   HumanMessage(sub_q)]
        for _ in range(3):  # bounded tool loop, a local stop condition
            ai = llm.invoke(private)
            private.append(ai)
            if not ai.tool_calls:
                break
            for call in ai.tool_calls:
                private.append(ToolMessage(search_notes.invoke(call["args"]), tool_call_id=call["id"]))
        notes.append(f"{sub_q} -> {ai.content or 'no answer found'}")
    return {"notes": notes, "trace": ["researcher"]}  # only distilled notes reach shared state


def writer(state: TeamState) -> dict:
    reply = model().invoke([
        SystemMessage("You are the writer. Use ONLY the notes given. Write a short, clear answer."),
        HumanMessage(f"Question: {state['question']}\nNotes:\n" + "\n".join(state["notes"])),
    ])
    return {"draft": reply.content, "trace": ["writer"]}

"""Supervisor, handoffs and termination rules."""
import os
from typing import Literal, Optional

from langchain_core.messages import HumanMessage, SystemMessage
from langgraph.graph import END, START, StateGraph
from langgraph.types import Command
from pydantic import BaseModel

from src.agents import model, planner, researcher, writer
from src.state import TeamState

Choice = Literal["planner", "researcher", "writer", "FINISH"]


class Route(BaseModel):
    next: Choice
    reason: str


def validate_route(choice: Optional[str], state: TeamState) -> str:
    """Deterministic guard on top of the LLM's proposal. It is pure, so it can be tested."""
    if state.get("steps", 0) >= int(os.getenv("MAX_STEPS", "6")):
        return "FINISH"                      # stop condition: turn budget used up
    if state.get("draft"):
        return "FINISH"                      # stop condition: the goal is reached
    if not state.get("plan"):
        return "planner"                     # precondition: nothing to research yet
    if not state.get("notes"):
        return "researcher"                  # precondition: nothing to write from yet
    if choice in (None, "FINISH", "planner"):
        return "writer"                      # no finishing without a draft and no re-plan loops
    return choice


def supervisor(state: TeamState) -> Command[Literal["planner", "researcher", "writer", "__end__"]]:
    forced = validate_route(None, state)
    if forced == "FINISH":                    # skip the LLM call when the rules already decide
        nxt = forced
    else:
        status = (f"question={state['question']!r}; plan_steps={len(state.get('plan', []))}; "
                  f"notes={len(state.get('notes', []))}; draft={'yes' if state.get('draft') else 'no'}")
        route = model().with_structured_output(Route).invoke([
            SystemMessage("You are the supervisor. Choose the next worker: planner plans, researcher "
                          "gathers notes, writer writes the answer. Choose FINISH only when a draft exists."),
            HumanMessage(status),
        ])
        nxt = validate_route(route.next, state)
    update = {"steps": state.get("steps", 0) + 1, "trace": [f"supervisor->{nxt}"]}
    # The handoff: move control to the chosen node and update shared state in one step
    return Command(goto=END if nxt == "FINISH" else nxt, update=update)


def build_graph():
    g = StateGraph(TeamState)
    g.add_node("supervisor", supervisor)
    for name, fn in (("planner", planner), ("researcher", researcher), ("writer", writer)):
        g.add_node(name, fn)
        g.add_edge(name, "supervisor")       # every worker reports back to the supervisor
    g.add_edge(START, "supervisor")
    return g.compile()

