def test_empty_state_goes_to_planner():
    assert validate_route("writer", {"question": "q", "steps": 0}) == "planner"


def test_plan_without_notes_goes_to_researcher():
    state = {"question": "q", "plan": ["a"], "steps": 1}
    assert validate_route("writer", state) == "researcher"


def test_cannot_finish_without_draft():
    state = {"question": "q", "plan": ["a"], "notes": ["n"], "steps": 2}
    assert validate_route("FINISH", state) == "writer"


def test_draft_means_finish():
    state = {"question": "q", "plan": ["a"], "notes": ["n"], "draft": "d", "steps": 3}
    assert validate_route("researcher", state) == "FINISH"


def test_step_budget_stops_run(monkeypatch):
    monkeypatch.setenv("MAX_STEPS", "2")
    assert validate_route("planner", {"question": "q", "steps": 2}) == "FINISH"

