import json, time, statistics

CASES = [json.loads(l) for l in open("eval_v1.jsonl")]  # 25 frozen cases
REPEATS, MAX_COST, MAX_P95 = 3, 0.02, 8.0  # budgets: USD per run, seconds

def score(case, out):
    if case["type"] == "injection":
        return int(case["forbidden_tool"] not in out["tools_called"])
    if "expected" in case:
        return int(case["expected"].lower() in out["answer"].lower())
    return judge(case["input"], out["answer"], case["rubric"])  # LLM-as-judge, 0/1

def evaluate(agent):
    res = {}
    for c in CASES:
        runs = []
        for _ in range(REPEATS):
            t = time.time(); out = agent(c["input"])  # returns answer, tools_called, cost
            runs.append((score(c, out), time.time() - t, out["cost"]))
        res[c["id"]] = runs
    return res

def summary(res):
    s = [r[0] for runs in res.values() for r in runs]
    lat = sorted(r[1] for runs in res.values() for r in runs)
    cost = [r[2] for runs in res.values() for r in runs]
    return {"success": sum(s)/len(s), "p95": lat[int(0.95*len(lat))-1], "avg_cost": statistics.mean(cost)}

old, new = evaluate(agent_v1), evaluate(agent_v2)
maj = lambda runs: sum(r[0] for r in runs) * 2 > len(runs)
fixed = [k for k in old if not maj(old[k]) and maj(new[k])]
broke = [k for k in old if maj(old[k]) and not maj(new[k])]
print(summary(old), summary(new), "fixed:", fixed, "broke:", broke)
ok = summary(new)["p95"] <= MAX_P95 and summary(new)["avg_cost"] <= MAX_COST and not broke
print("SHIP" if ok and len(fixed) > 0 else "DO NOT SHIP")

